        if exp_result:
            text += f" ({exp_result['exp']}/{exp_result['exp_to_next']})"

        # Stage 17.14.1.1 sends level-up information separately.

    premium_gold = float(reward.get("premium_gold_bonus", 0.0) or 0.0)
