def get_pve_skill_action_state(user_id, mob, skill):
    """Return current PvE skill UI state without mutating DB or combat state."""
    del user_id
    mob = mob or {}
    skill = skill or {}
    name = str(skill.get("name") or skill.get("key") or "Навичка")
    key = str(skill.get("key") or "")

    cooldowns = mob.get("skill_cooldowns") or {}
    cooldown = max(0, int(cooldowns.get(key, 0) or 0))
    if cooldown > 0:
        return _state(
            skill, False, "cooldown",
            f"⏳ {name} · ще {_turns_uk(cooldown)}",
            f"⏳ {name} ще перезаряджається. Залишилось: {_turns_uk(cooldown)}.",
            remaining=cooldown,
        )

    player_stunned = max(0, int(mob.get("player_stunned_turns", 0) or 0))
    player_effects = mob.get("player_effects") or {}
    controlled = player_stunned > 0 or any(
        str(effect.get("type") or "").lower() in {"stun", "silence", "control"}
        and int(effect.get("turns", 0) or 0) > 0
        for effect in player_effects.values()
        if isinstance(effect, dict)
    )
    if controlled:
        return _state(
            skill, False, "control_state",
            f"🔒 {name} · зараз недоступна",
            f"🔒 {name} зараз недоступна через ефект контролю.",
        )

    cost_type = str(skill.get("cost_type") or "")
    cost = get_pve_effective_skill_cost(mob, skill)

    if cost_type == "rage":
        current = max(0, int(mob.get("player_rage", 0) or 0))
        if current < cost:
            return _state(skill, False, "not_enough_rage",
                          f"🔒 {name} · потрібно {cost} Люті",
                          f"🔴 Недостатньо Люті для {name}. Потрібно: {cost}, доступно: {current}.",
                          required=cost, available_amount=current)

    elif cost_type == "rage_all_min":
        required = max(0, int(skill.get("min_cost", 30) or 30))
        current = max(0, int(mob.get("player_rage", 0) or 0))
        if current < required:
            return _state(skill, False, "not_enough_rage",
                          f"🔒 {name} · потрібно {required} Люті",
                          f"🔴 Недостатньо Люті для {name}. Потрібно мінімум: {required}, доступно: {current}.",
                          required=required, available_amount=current)

    elif cost_type in {"combat_energy", "combat_energy_combo"}:
        current = max(0, int(mob.get("player_combat_energy", 0) or 0))
        maximum = max(0, int(mob.get("player_max_combat_energy", 100) or 100))
        projected = min(maximum, current + 20)
        if projected < cost:
            return _state(skill, False, "not_enough_combat_energy",
                          f"🔒 {name} · потрібно {cost} Енергії",
                          f"🟡 Недостатньо Енергії для {name}. Потрібно: {cost}, на початку ходу буде доступно: {projected}.",
                          required=cost, available_amount=projected)
        if cost_type == "combat_energy_combo":
            required_combo = max(1, int(skill.get("min_combo", 1) or 1))
            combo = max(0, int(mob.get("player_combo_points", 0) or 0))
            if combo < required_combo:
                return _state(skill, False, "not_enough_combo",
                              f"🔒 {name} · потрібно {required_combo} комбо",
                              f"⚔️ Недостатньо комбо для {name}. Потрібно: {required_combo}, доступно: {combo}.",
                              required=required_combo, available_amount=combo)

    elif cost_type == "mana":
        current = max(0, int(mob.get("player_mp", 0) or 0))
        maximum = max(0, int(mob.get("player_max_mp", 0) or 0))
        if skill.get("key") == "mage_arcane_flow" and maximum > 0 and current >= maximum:
            return _state(skill, False, "mana_already_full",
                          f"🔒 {name} · Мана вже повна",
                          "🔵 Мана вже повна.",
                          required=cost, available_amount=current, effective_cost=cost)
        if current < cost:
            return _state(skill, False, "not_enough_mana",
                          f"🔒 {name} · потрібно {cost} Мани",
                          f"🔵 Недостатньо Мани для {name}. Потрібно: {cost}, доступно: {current}.",
                          required=cost, available_amount=current, effective_cost=cost)

    return _state(skill, True, "ok", f"✨ {name}", "", effective_cost=cost)

def calculate_player_hit_chance(player_dex, mob_dex):
    """Return the approved PvE normal-attack hit chance in percent."""
    try:
        player_dex = float(player_dex or 0)
    except (TypeError, ValueError):
        player_dex = 0.0
    try:
        mob_dex = float(mob_dex or 0)
    except (TypeError, ValueError):
        mob_dex = 0.0

    chance = 95.0 + ((player_dex - mob_dex) * 0.5)
    return max(50.0, min(95.0, chance))

def roll_player_normal_attack_hit(player_dex, mob_dex, rng=None):
    """Roll PvE normal-attack hit before crit and damage calculations."""
    chance = calculate_player_hit_chance(player_dex, mob_dex)
    roller = rng if rng is not None else random
    roll = int(roller.randint(1, 100))
    return {
        "hit": roll <= chance,
        "chance": chance,
        "roll": roll,
    }

def skill_requires_pve_hit_roll(skill):
    """Return True only for enemy-directed PvE player skills."""
    damage_multiplier = float(skill.get("damage_multiplier", 0) or 0)
    effect = str(skill.get("effect", "") or "")
    return damage_multiplier > 0 or effect.startswith("enemy_")

def roll_player_pve_skill_hit(skill, player_dex, player_int, mob, rng=None):
    """Resolve physical DEX/DEX or magical INT/WIS for offensive PvE skills."""
    if not skill_requires_pve_hit_roll(skill):
        return {"required": False, "hit": True, "chance": None, "roll": None}
    attack_type = str(skill.get("attack_type", "") or "")
    if attack_type == "physical":
        attacker_accuracy = player_dex
        target_avoidance = mob["dex"]
    elif attack_type == "magical":
        attacker_accuracy = player_int
        target_avoidance = mob["wis"]
    else:
        raise ValueError(f"Offensive PvE skill has invalid attack_type: {attack_type!r}")
    chance = calculate_player_hit_chance(attacker_accuracy, target_avoidance)
    roller = rng if rng is not None else random
    roll = int(roller.randint(1, 100))
    return {"required": True, "hit": roll <= chance, "chance": chance, "roll": roll}

def roll_is_elite():
    roll = random.randint(1, 100)
    return roll <= ELITE_CHANCE_PERCENT

def get_available_mobs(player_level, location_id="start_path"):
    mobs = get_mobs_for_location(location_id)
    available = []

    for mob in mobs:
        mob_level = int(mob.get("level", 1))
        min_player_level = int(mob.get("min_player_level", 1))

        if min_player_level <= player_level and player_level - 1 <= mob_level <= player_level + 1:
            available.append(mob)

    if available:
        return available

    fallback = []

    for mob in mobs:
        min_player_level = int(mob.get("min_player_level", 1))

        if min_player_level <= player_level:
            fallback.append(mob)

    return fallback

def generate_mob(player_level, location_id="start_path"):
    def _build_normal_mob(selected_template=None):
        available_mobs = get_available_mobs(
            player_level=player_level,
            location_id=location_id
        )

        if not available_mobs:
            base_template = get_mobs_for_location(location_id)[0]
        else:
            base_template = random.choice(available_mobs)

        if selected_template is None:
            return build_mob(base_template)

        # Stage 18.29.4l: canonical event-template materialization
        # Event packages provide identity/presentation. Canonical ordinary
        # templates remain the owner of combat ranges and reward defaults.
        event_template = dict(selected_template)
        runtime_template = dict(base_template)
        runtime_template.update({
            "name": event_template["name"],
            "attack_type": event_template.get(
                "attack_type",
                runtime_template.get("attack_type", "physical"),
            ),
            "level": int(player_level),
            "location_id": location_id,
        })
        return build_mob(runtime_template)

    encounter = generate_hunt_encounter(
        player_level=player_level,
        location_id=location_id,
        normal_mob_factory=_build_normal_mob,
        elite_modifier=apply_elite_modifier,
        elite_roll=roll_is_elite,
        rng=random,
        boss_enabled=BOSS_ENCOUNTERS_ENABLED,
        boss_chance_percent=BOSS_ENCOUNTER_CHANCE_PERCENT,
    )
    return encounter["mob"]

