def projected_round_cooldown(participant: Mapping[str, Any], skill_key: str) -> int:
    """Cooldown visible to the action validator after the engine start-of-round tick."""
    stored = int(dict(participant.get("cooldowns") or {}).get(str(skill_key), 0) or 0)
    return max(0, stored - 1)

def get_pvp_effective_skill_cost(skill: Mapping[str, Any], max_mp: Any) -> int:
    """Return canonical Mana cost or unchanged physical-resource cost."""
    if str(skill.get("cost_type") or "") == "mana":
        return calculate_mana_skill_cost(skill, max(0, int(max_mp or 0)))
    return max(0, int(skill.get("cost") or 0))

def projected_round_resource(participant: Mapping[str, Any]) -> int:
    value = int(participant.get("resource_value", participant.get("resource", 0)) or 0)
    if str(participant.get("resource_type") or "") in {"combat_energy", "combat_energy_combo"}:
        return min(PVP_COMBAT_ENERGY_MAX, value + 20)
    return value

def validate_pvp_action_choice(
    participant: Mapping[str, Any],
    action_type: str,
    skill_key: str | None = None,
    *,
    catalog: Mapping[str, tuple[dict[str, Any], ...]] | None = None,
) -> dict[str, Any]:
    """Prevalidate a UI action without mutating state or consuming the round.

    The pure round engine remains the final authority. This helper mirrors the
    engine's imminent start-of-round cooldown tick and Combat Energy regeneration
    so a choice accepted by the UI is not rejected later for stale resource data.
    """
    action_type = str(action_type or "")
    if action_type == "basic_attack":
        return {"success": True, "reason": "ok", "message": ""}
    if action_type != "skill" or not skill_key:
        return {"success": False, "reason": "invalid_action", "message": "❌ Невідома бойова дія. Оберіть іншу дію."}

    class_key = str(participant.get("class_key") or "")
    skill = get_production_pvp_skill(class_key, str(skill_key), catalog or load_production_pvp_skill_catalog())
    if not skill:
        return {"success": False, "reason": "unknown_skill", "message": "❌ Ця навичка не належить вашому класу. Оберіть іншу дію."}

    name = str(skill.get("name") or skill_key)
    cooldown = projected_round_cooldown(participant, str(skill_key))
    if cooldown > 0:
        return {
            "success": False,
            "reason": "skill_on_cooldown",
            "remaining": cooldown,
            "message": f"⏳ «{name}» ще відновлюється. Залишилося раундів: {cooldown}. Оберіть іншу дію.",
        }

    cost_type = str(skill.get("cost_type") or "")
    maximum_mp = max(0, int(participant.get("max_mp") or 0))
    cost = get_pvp_effective_skill_cost(skill, maximum_mp)
    resource = projected_round_resource(participant)
    mp = int(participant.get("mp") or 0)
    combo = int(participant.get("combo") or 0)

    if cost_type == "mana" and mp < cost:
        return {"success": False, "reason": "not_enough_mana", "required": cost, "available": mp, "message": f"🔷 Недостатньо мани для «{name}». Потрібно: {cost} MP, доступно: {mp} MP. Оберіть іншу дію."}
    if cost_type == "rage" and resource < cost:
        return {"success": False, "reason": "not_enough_rage", "required": cost, "available": resource, "message": f"🔥 Недостатньо Люті для «{name}». Потрібно: {cost}, доступно: {resource}. Оберіть іншу дію."}
    if cost_type == "rage_all_min":
        minimum = max(0, int(skill.get("min_cost") or 0))
        if resource < minimum:
            return {"success": False, "reason": "not_enough_rage", "required": minimum, "available": resource, "message": f"🔥 Недостатньо Люті для «{name}». Потрібно щонайменше: {minimum}, доступно: {resource}. Оберіть іншу дію."}
    if cost_type in {"combat_energy", "combat_energy_combo"} and resource < cost:
        return {"success": False, "reason": "not_enough_combat_energy", "required": cost, "available": resource, "message": f"⚡ Недостатньо Енергії для «{name}». Потрібно: {cost}, після відновлення доступно: {resource}. Оберіть іншу дію."}
    if cost_type == "combat_energy_combo":
        minimum_combo = int(skill.get("min_combo") or 1)
        if combo < minimum_combo:
            return {"success": False, "reason": "not_enough_combo", "required": minimum_combo, "available": combo, "message": f"🔗 Недостатньо комбо для «{name}». Потрібно: {minimum_combo}, доступно: {combo}. Оберіть іншу дію."}

    return {
        "success": True,
        "reason": "ok",
        "message": "",
        "skill": dict(skill),
        "projected_resource": resource,
        "projected_cooldown": cooldown,
    }

def pvp_skill_button_state(participant: Mapping[str, Any], skill: Mapping[str, Any]) -> dict[str, Any]:
    result = validate_pvp_action_choice(participant, "skill", str(skill.get("key") or ""), catalog={str(participant.get("class_key") or ""): (dict(skill),)})
    name = str(skill.get("name") or skill.get("key") or "Навичка")
    if result.get("success"):
        return {"available": True, "label": f"✨ {name}", "reason": "ok"}
    if result.get("reason") == "skill_on_cooldown":
        return {"available": False, "label": f"⏳ {name} · {int(result.get('remaining') or 0)}", "reason": result.get("reason")}
    return {"available": False, "label": f"🔒 {name}", "reason": result.get("reason")}

def _effect_value(effect: Mapping[str, Any], key: str, default: float = 0.0) -> float:
    try:
        return float(effect.get(key, default))
    except (TypeError, ValueError):
        return default

def _tick_start(actor: PvpActorState, events: list[dict[str, Any]]) -> None:
    # PvE parity: Scout and Rogue restore 20 combat energy at the start of every round,
    # before action cost validation. Energy is duel-local and capped at 100.
    if actor.resource_type in {"combat_energy", "combat_energy_combo"}:
        before_energy = int(actor.resource or 0)
        actor.resource = min(PVP_COMBAT_ENERGY_MAX, before_energy + 20)
        restored = actor.resource - before_energy
        if restored > 0:
            events.append({
                "type": "combat_energy_regen",
                "user_id": actor.user_id,
                "value": restored,
                "before": before_energy,
                "after": actor.resource,
                "maximum": PVP_COMBAT_ENERGY_MAX,
            })
    for key, effect in list(actor.effects.items()):
        kind = effect.get("kind", key)
        if kind in {"poison", "bleed", "dot"}:
            damage = max(0, int(round(_effect_value(effect, "power"))))
            actor.hp = max(0, actor.hp - damage)
            events.append({"type": "dot_tick", "user_id": actor.user_id, "effect": key, "value": damage})
        elif kind in {"hot", "heal_over_time"}:
            healing = max(0, int(round(_effect_value(effect, "power") * PVP_HEALING_MULTIPLIER)))
            before = actor.hp
            actor.hp = min(actor.max_hp, actor.hp + healing)
            events.append({
                "type": "hot_tick", "user_id": actor.user_id, "effect": key,
                "value": actor.hp - before, "nominal_value": healing,
                "hp_before": before, "hp_after": actor.hp, "max_hp": actor.max_hp,
            })
        remaining = int(effect.get("duration", 1)) - 1
        if remaining <= 0:
            del actor.effects[key]
            events.append({"type": "effect_expired", "user_id": actor.user_id, "effect": key})
        else:
            effect["duration"] = remaining
    for key in list(actor.cooldowns):
        actor.cooldowns[key] = max(0, int(actor.cooldowns[key]) - 1)
        if actor.cooldowns[key] == 0:
            del actor.cooldowns[key]

def _terminal(a: PvpActorState, b: PvpActorState, reason: str) -> tuple[bool, int | None, str | None]:
    if a.hp <= 0 and b.hp <= 0:
        return True, None, "draw_" + reason
    if a.hp <= 0:
        return True, b.user_id, reason
    if b.hp <= 0:
        return True, a.user_id, reason
    return False, None, None

def _replace_effect(target: PvpActorState, key: str, kind: str, power: float, duration: int, source_id: int) -> dict[str, Any]:
    effect = {"kind": kind, "power": power, "duration": max(1, duration), "source_id": source_id}
    target.effects[key] = effect
    return {"target_id": target.user_id, "effect_key": key, **effect}

def _shield_absorb(target: PvpActorState, incoming: int, events: list[dict[str, Any]]) -> int:
    shield = target.effects.get("shield")
    if not shield or incoming <= 0:
        return incoming
    remaining = max(0, int(shield.get("remaining", shield.get("power", 0))))
    absorbed = min(remaining, incoming)
    remaining -= absorbed
    if remaining <= 0:
        target.effects.pop("shield", None)
    else:
        shield["remaining"] = remaining
    events.append({"type": "shield_absorb", "user_id": target.user_id, "value": absorbed})
    return incoming - absorbed

def resolve_pvp_round(round_number: int, revision: int, actor_a: PvpActorState, actor_b: PvpActorState, action_a: PvpActionIntent, action_b: PvpActionIntent, seed: int | None = None, catalog: Mapping[str, tuple[dict[str, Any], ...]] | None = None) -> PvpRoundResult:
    if {action_a.user_id, action_b.user_id} != {actor_a.user_id, actor_b.user_id}:
        raise PvpRoundError("action actor mismatch")
    rng = random.Random(seed)
    skills = catalog or load_production_pvp_skill_catalog()
    a, b = actor_a.clone(), actor_b.clone()
    events: list[dict[str, Any]] = []
    _tick_start(a, events); _tick_start(b, events)
    terminal, winner, reason = _terminal(a, b, "periodic")
    no = PvpActionOutcome(a.user_id, "none", None, False, "terminal_before_actions")
    if terminal:
        return PvpRoundResult(round_number, revision, a.to_dict(), b.to_dict(), (no, PvpActionOutcome(b.user_id, "none", None, False, "terminal_before_actions")), tuple(events), True, winner, reason)

    forced: dict[int, str] = {}
    for actor in (a, b):
        if actor.stunned_next:
            forced[actor.user_id] = "stunned_skip"
            actor.stunned_next = False

    prepared: dict[int, dict[str, Any]] = {}
    outcomes: dict[int, PvpActionOutcome] = {}
    pairs = ((a, b, action_a if action_a.user_id == a.user_id else action_b), (b, a, action_b if action_b.user_id == b.user_id else action_a))
    for actor, target, intent in pairs:
        action_type = forced.get(actor.user_id, intent.action_type)
        if action_type in {"afk_skip", "stunned_skip"}:
            if action_type == "afk_skip": actor.consecutive_afk += 1
            else: actor.consecutive_afk = 0
            outcomes[actor.user_id] = PvpActionOutcome(actor.user_id, action_type, None, True, action_type)
            continue
        actor.consecutive_afk = 0
        if action_type == "basic_attack":
            prepared[actor.user_id] = {"actor": actor, "target": target, "intent": intent, "skill": None, "cost": 0, "combo_spent": 0}
            continue
        if action_type != "skill" or not intent.skill_key:
            outcomes[actor.user_id] = PvpActionOutcome(actor.user_id, action_type, intent.skill_key, False, "invalid_action")
            continue
        skill = get_production_pvp_skill(actor.class_key, intent.skill_key, skills)
        if not skill:
            outcomes[actor.user_id] = PvpActionOutcome(actor.user_id, action_type, intent.skill_key, False, "unknown_skill")
            continue
        if actor.cooldowns.get(intent.skill_key, 0) > 0:
            outcomes[actor.user_id] = PvpActionOutcome(actor.user_id, action_type, intent.skill_key, False, "skill_on_cooldown")
            continue
        paid, pay_reason, cost, combo_spent = _pay(actor, skill)
        if not paid:
            outcomes[actor.user_id] = PvpActionOutcome(actor.user_id, action_type, intent.skill_key, False, pay_reason)
            continue
        cooldown = int(skill.get("cooldown") or 0)
        if cooldown > 0: actor.cooldowns[intent.skill_key] = cooldown
        prepared[actor.user_id] = {"actor": actor, "target": target, "intent": intent, "skill": skill, "cost": cost, "combo_spent": combo_spent}

    # Utility and defensive effects are prepared before both damage packets.
    for item in prepared.values():
        skill = item["skill"]
        if skill and (skill.get("no_damage") or float(skill.get("damage_multiplier") or 0) == 0):
            applied, gained, combo_gain = _special(item["actor"], item["target"], skill, 0, rng)
            item["actor"].resource = _clamp(item["actor"].resource + gained, 0, PVP_COMBAT_ENERGY_MAX if "energy" in item["actor"].resource_type else 100)
            item["actor"].combo = _clamp(item["actor"].combo + combo_gain, 0, 3)
            outcomes[item["actor"].user_id] = PvpActionOutcome(item["actor"].user_id, "skill", item["intent"].skill_key, True, "ok", resource_spent=item["cost"], combo_spent=item["combo_spent"], resource_gained=gained, combo_gained=combo_gain, applied_effects=tuple(applied))

    damage_packets: list[tuple[PvpActorState, PvpActorState, int, bool, bool, dict[str, Any]]] = []
    for item in prepared.values():
        actor, target, skill = item["actor"], item["target"], item["skill"]
        if skill and (skill.get("no_damage") or float(skill.get("damage_multiplier") or 0) == 0):
            continue
        attack_type = str((skill or {}).get("attack_type") or resolve_basic_attack_type(actor.class_key))
        damage, critical, dodged = _base_damage(actor, target, attack_type, rng)
        multiplier = float((skill or {}).get("damage_multiplier") or 1.0)
        if skill:
            multiplier *= float(PVP_CLASS_SKILL_DAMAGE_MULTIPLIER.get(actor.class_key, 1.0))
        damage = 0 if dodged else max(1, round(damage * multiplier))
        # Production flags use the same PvE definitions; no PvP-specific constants are introduced.
        if skill and skill.get("scales_with_spent_rage"):
            damage = ma

def from_dict(cls, value: Mapping[str, Any]) -> "PvpActorState":
        fields = cls.__dataclass_fields__
        return cls(**{key: value[key] for key in fields if key in value})

def __init__(self, project_root: Path, seed: int, max_turns: int=100):
        self.root=Path(project_root); self.rng=SimulationRng(seed); self.seed=int(seed); self.max_turns=max_turns
        self.skills=load_production_skill_catalog(self.root)

def _effective_def(self, actor: BattleActor, kind: str) -> int:
        value=float(actor.mdef if kind=="magical" else actor.pdef)
        key="mdef_percent" if kind=="magical" else "pdef_percent"
        for effect in actor.effects.values(): value *= 1+float(effect.get(key,0))/100
        return max(0,int(round(value)))

def _tick_start(self, actor: BattleActor, actions: List[BattleAction], turn: int):
        for key in list(actor.cooldowns): actor.cooldowns[key]=max(0,actor.cooldowns[key]-1)
        if actor.resource_type in {"combat_energy","combat_energy_combo"}: actor.resource=min(actor.max_resource,actor.resource+20)
        for key in list(actor.effects):
            e=actor.effects[key]
            if e.get("type")=="dot" and actor.alive:
                dmg=min(actor.hp,int(e.get("damage",0))); actor.hp-=dmg
                actions.append(BattleAction(turn,"effect",key,damage=dmg,details={"target":actor.name}))
            elif e.get("type")=="hot" and actor.alive:
                heal=min(actor.max_hp-actor.hp,int(e.get("heal",0))); actor.hp+=heal
                actions.append(BattleAction(turn,"effect",key,healing=heal,details={"target":actor.name}))
            e["turns"]=int(e.get("turns",0))-1
            if e["turns"]<=0: del actor.effects[key]

def _absorb(self, player: BattleActor, damage: int) -> int:
        for key,e in list(player.effects.items()):
            if e.get("type")=="shield" and damage>0:
                used=min(damage,int(e.get("absorb_left",0))); damage-=used; e["absorb_left"]-=used
                if e["absorb_left"]<=0: del player.effects[key]
        return damage

def _effective_skill_cost(self, actor: BattleActor, skill: Dict[str,Any]) -> int:
        """Return canonical Mana cost or the unchanged physical-resource cost."""
        if str(skill.get("cost_type") or "") == "mana":
            return calculate_mana_skill_cost(skill, actor.max_resource)
        return max(0, int(skill.get("cost", 0) or 0))

def _can_use(self, actor: BattleActor, skill: Dict[str,Any]) -> bool:
        if actor.cooldowns.get(skill["key"],0)>0: return False
        typ=skill["cost_type"]; cost=self._effective_skill_cost(actor, skill)
        if typ=="rage_all_min": return actor.resource>=int(skill.get("min_cost",30))
        if typ=="combat_energy_combo": return actor.resource>=cost and actor.combo>=int(skill.get("min_combo",1))
        return actor.resource>=cost

def _pay(self, actor: BattleActor, skill: Dict[str,Any]) -> Dict[str,int]:
        typ=skill["cost_type"]; cost=self._effective_skill_cost(actor, skill); spent={"rage":0,"combo":0}
        if typ=="rage_all_min": spent["rage"]=actor.resource; actor.resource=0
        else: actor.resource=max(0,actor.resource-cost)
        if typ=="combat_energy_combo": spent["combo"]=actor.combo; actor.combo=0
        return spent

def _apply_effect(self, player: BattleActor, mob: BattleActor, skill: Dict[str,Any], damage: int):
        effect=skill.get("effect")
        if effect=="enemy_pdef_down": mob.effects["warrior_pdef"]={"turns":3,"pdef_percent":-30}
        elif effect=="enemy_pdef_trap": mob.effects["scout_pdef"]={"turns":2,"pdef_percent":-50}
        elif effect in {"enemy_bleed","enemy_poison"}: mob.effects[effect]={"type":"dot","turns":3,"damage":max(2,int(round(max(1,damage)*.30)))}
        elif effect=="player_shield": player.effects["knight_shield"]={"type":"shield","turns":3,"absorb_left":max(15,int(player.pdef*2+player.level*3))}
        elif effect=="player_hot": player.effects["priest_hot"]={"type":"hot","turns":PRIEST_HEALING_DURATION_TURNS,"heal":max(5,int(round(player.max_hp*.10)))}
        elif effect=="restore_mana_percent": player.resource=min(player.max_resource,player.resource+calculate_mana_restore_amount(player.max_resource,skill.get("restore_max_mp_percent",25)))
        elif effect=="player_cleanse_mdef_buff":
            player.effects={k:v for k,v in player.effects.items() if not v.get("negative")}; player.effects["priest_mdef"]={"turns":3,"mdef_percent":30}
            player.resource=min(player.max_resource,player.resource+calculate_mana_restore_amount(player.max_resource,skill.get("restore_max_mp_percent",15)))

def _player_action(self, turn, class_key, p, m, actions):
        skill=self._choose(class_key,p,m)
        if skill:
            spent=self._pay(p,skill); mult=float(skill.get("damage_multiplier",0)); damage=0; crit=False
            if mult>0:
                attack=p.magic_attack if skill["attack_type"]=="magical" else p.attack
                base=call_rule("player_attack",attack,self._effective_def(m,skill["attack_type"]),p.dex,p.wis,p.level,skill["attack_type"],p.weapon_min_damage,p.weapon_max_damage,rng=self.rng)
                damage=max(1,int(round(int(base["damage"])*mult))); crit=bool(base["is_crit"])
                if skill.get("scales_with_spent_rage"): damage=max(1,int(round(damage*(1+spent["rage"]/100))))
                if skill.get("scales_with_combo"): damage=max(1,int(round(damage*(1+spent["combo"]*.50))))
                if skill.get("scales_with_player_pdef"): damage+=max(1,int(round(p.pdef*.50)))
                m.hp=max(0,m.hp-damage)
            if int(skill.get("stun_chance",0)) and self.rng.randint(1,100)<=int(skill["stun_chance"]): m.effects["stunned"]={"turns":1,"stun":True}
            if int(skill.get("combo_gain",0)): p.combo=min(p.max_combo,p.combo+int(skill["combo_gain"]))
            if int(skill.get("extra_rage",0)): p.resource=min(p.max_resource,p.resource+int(skill["extra_rage"]))
            p.cooldowns[skill["key"]]=int(skill.get("cooldown",0)); self._apply_effect(p,m,skill,damage)
            actions.append(BattleAction(turn,"player",skill["key"],damage=damage,critical=crit,details={"resource":p.resource,"combo":p.combo})); return
        kind=resolve_basic_attack_type(class_key); attack=p.magic_attack if kind=="magical" else p.attack
        raw=call_rule("player_attack",attack,self._effective_def(m,kind),p.dex,p.wis,p.level,kind,p.weapon_min_damage,p.weapon_max_damage,rng=self.rng)
        damage=int(raw["damage"]); m.hp=max(0,m.hp-damage)
        if p.resource_type=="rage": p.resource=min(p.max_resource,p.resource+15)
        actions.append(BattleAction(turn,"player","basic_attack",damage=damage,critical=bool(raw["is_crit"])))

def load_production_skill_catalog(project_root: Path) -> Dict[str, List[Dict[str, Any]]]:
    path = Path(project_root) / "handlers" / "combat.py"
    tree = ast.parse(path.read_text(encoding="utf-8-sig"), filename=str(path))
    candidates=[]
    for node in tree.body:
        if isinstance(node, ast.Assign):
            for target in node.targets:
                if isinstance(target, ast.Name) and target.id == "CLASS_SKILLS_V1":
                    candidates.append(ast.literal_eval(node.value))
    if len(candidates) != 1:
        raise SkillCatalogError(f"expected one CLASS_SKILLS_V1, found {len(candidates)}")
    catalog=candidates[0]
    required={"warrior","knight","scout","rogue","mage","priest"}
    if set(catalog) != required:
        raise SkillCatalogError(f"class catalog mismatch: {sorted(catalog)}")
    for class_key, skills in catalog.items():
        if len(skills) != 3:
            raise SkillCatalogError(f"{class_key} must have 3 skills")
        for skill in skills:
            for key in ("key","cost_type","cost","cooldown","damage_multiplier","attack_type"):
                if key not in skill:
                    raise SkillCatalogError(f"{class_key} skill missing {key}")
    return deepcopy(catalog)

def _int(value: Any, default: int = 0) -> int:
    try:
        return int(value)
    except (TypeError, ValueError):
        return int(default)

def _templates_for_level(location_id: str, level: int) -> list[Mapping[str, Any]]:
    templates = list(get_mobs_for_location(location_id) or ())
    exact = [row for row in templates if _int(row.get("level"), 1) == level]
    if exact:
        return exact
    if not templates:
        return []
    distance = min(abs(_int(row.get("level"), 1) - level) for row in templates)
    return [row for row in templates if abs(_int(row.get("level"), 1) - level) == distance]

def _average_range(templates, minimum_key, maximum_key, fallback=1):
    if not templates:
        return int(fallback), int(fallback)
    mins = [_int(row.get(minimum_key, fallback), fallback) for row in templates]
    maxs = [_int(row.get(maximum_key, fallback), fallback) for row in templates]
    return max(1, round(sum(mins) / len(mins))), max(1, round(sum(maxs) / len(maxs)))

def choose_boss_action(boss: Mapping[str, Any], rng=None) -> dict[str, Any]:
    definition = boss.get("boss_definition") or {}
    state = boss.get("boss_state") or {}
    phase_key = "ai_after_enrage" if state.get("enrage_used") else "ai_before_enrage"
    choices = tuple(definition.get(phase_key) or ())
    if not choices:
        raise ValueError(f"Boss AI has no choices for phase: {phase_key}")
    total = sum(float(weight) for _, weight in choices)
    if total <= 0:
        raise ValueError("Boss AI weights must be positive")
    rng = rng or random
    roll = rng.random() * total
    running = 0.0
    selected = choices[-1][0]
    for skill_key, weight in choices:
        running += float(weight)
        if roll <= running:
            selected = skill_key
            break
    skill = dict((definition.get("skills") or {}).get(selected) or {})
    if not skill:
        raise ValueError(f"Unknown boss skill: {selected}")
    return {"skill_key": selected, "skill": skill, "phase": phase_key}

def validate_boss_definitions() -> dict[str, Any]:
    findings = []
    locations = set()
    for boss_key, definition in BOSS_DEFINITIONS.items():
        if definition.get("boss_key") != boss_key:
            findings.append(f"{boss_key}: boss_key mismatch")
        location_id = str(definition.get("location_id") or "")
        if not location_id:
            findings.append(f"{boss_key}: location_id missing")
        elif location_id in locations:
            findings.append(f"{boss_key}: duplicate location_id {location_id}")
        locations.add(location_id)
        if _int(definition.get("level_min"), 0) > _int(definition.get("level_max"), 0):
            findings.append(f"{boss_key}: invalid level range")
        for phase in ("ai_before_enrage", "ai_after_enrage"):
            rows = tuple(definition.get(phase) or ())
            weight_sum = sum(float(weight) for _, weight in rows)
            if abs(weight_sum - 1.0) > 1e-9:
                findings.append(f"{boss_key}: {phase} weights={weight_sum}")
            for skill_key, _ in rows:
                if skill_key not in (definition.get("skills") or {}):
                    findings.append(f"{boss_key}: missing skill {skill_key}")
        enrage = definition.get("enrage") or {}
        special = enrage.get("special_skill_key")
        if special not in (definition.get("skills") or {}):
            findings.append(f"{boss_key}: missing enrage special {special}")
        if enrage.get("special_replaces_regular_action") is not True:
            findings.append(f"{boss_key}: enrage special must replace regular action")
    return {
        "version": BOSS_SCHEMA_VERSION,
        "verdict": "PASS" if not findings else "FAIL",
        "boss_count": len(BOSS_DEFINITIONS),
        "location_count": len(locations),
        "findings": findings,
    }

def _boss_state(boss: dict[str, Any]) -> dict[str, Any]:
    state = boss.get("boss_state")
    if not isinstance(state, dict):
        state = create_boss_state()
        boss["boss_state"] = state
    defaults = create_boss_state()
    for key, value in defaults.items():
        state.setdefault(key, value)
    return state

def get_effective_boss_attack(boss: Mapping[str, Any]) -> int:
    """Return boss ATK after permanent enrage and temporary ATK buffs.

    Different ATK buffs are additive. The same temporary buff never stacks;
    applying it again only refreshes the duration in apply_boss_action_effects().
    """
    state = boss.get("boss_state") or {}
    permanent = float(state.get("permanent_attack_buff_percent", 0.0) or 0.0)
    temporary = 0.0
    if int(state.get("attack_buff_turns", 0) or 0) > 0:
        temporary = float(state.get("attack_buff_percent", 0.0) or 0.0)
    multiplier = 1.0 + (permanent + temporary) / 100.0
    return max(1, int(round(float(boss.get("attack", 1) or 1) * multiplier)))

def get_effective_boss_defenses(boss: Mapping[str, Any]) -> tuple[int, int]:
    state = boss.get("boss_state") or {}
    pdef_percent = 0.0
    mdef_percent = 0.0
    if int(state.get("defense_buff_turns", 0) or 0) > 0:
        pdef_percent = float(state.get("physical_defense_buff_percent", 0.0) or 0.0)
        mdef_percent = float(state.get("magical_defense_buff_percent", 0.0) or 0.0)
    pdef = max(0, int(round(float(boss.get("pdef", boss.get("def", 0)) or 0) * (1.0 + pdef_percent / 100.0))))
    mdef = max(0, int(round(float(boss.get("mdef", boss.get("def", 0)) or 0) * (1.0 + mdef_percent / 100.0))))
    return pdef, mdef

def calculate_boss_bleed_damage(actual_damage: int, skill: Mapping[str, Any]) -> int:
    """Bleed is based on actual post-defense damage and never crits."""
    fraction = float(skill.get("bleed_damage_fraction", 0.0) or 0.0)
    minimum = max(0, int(skill.get("bleed_min_damage", 1) or 1))
    if fraction <= 0 or int(actual_damage or 0) <= 0:
        return 0
    return max(minimum, int(round(int(actual_damage) * fraction)))

def tick_boss_temporary_buffs(boss: dict[str, Any]) -> dict[str, Any]:
    """Decrement temporary boss buffs after a completed boss action."""
    state = _boss_state(boss)
    expired = []
    if int(state.get("attack_buff_turns", 0) or 0) > 0:
        state["attack_buff_turns"] = int(state["attack_buff_turns"]) - 1
        if state["attack_buff_turns"] <= 0:
            state["attack_buff_turns"] = 0
            state["attack_buff_percent"] = 0.0
            expired.append("attack_buff")
    if int(state.get("defense_buff_turns", 0) or 0) > 0:
        state["defense_buff_turns"] = int(state["defense_buff_turns"]) - 1
        if state["defense_buff_turns"] <= 0:
            state["defense_buff_turns"] = 0
            state["physical_defense_buff_percent"] = 0.0
            state["magical_defense_buff_percent"] = 0.0
            expired.append("defense_buff")
    return {"boss_state": copy.deepcopy(state), "expired": expired}

def get_boss_enrage_threshold_hp(boss: Mapping[str, Any]) -> int:
    definition=boss.get("boss_definition") or {}
    enrage=definition.get("enrage") or {}
    fraction=float(enrage.get("hp_threshold_fraction",0.25) or 0.25)
    return max(1,int(float(boss.get("max_hp",1) or 1)*fraction))

def should_trigger_boss_enrage(boss: Mapping[str, Any]) -> bool:
    if not boss.get("is_boss") or int(boss.get("hp",0) or 0)<=0:
        return False
    state=boss.get("boss_state") or {}
    if state.get("enrage_used"):
        return False
    return int(boss.get("hp",0) or 0)<=get_boss_enrage_threshold_hp(boss)

def trigger_boss_enrage(boss: dict[str, Any]) -> dict[str, Any]:
    """Atomically mark enrage and return the automatic special action plan."""
    state=_boss_state(boss)
    if not should_trigger_boss_enrage(boss):
        return {"triggered":False,"reason":"not_eligible","action_plan":None,"events":[]}
    definition=boss.get("boss_definition") or {}
    enrage=definition.get("enrage") or {}
    special=str(enrage.get("special_skill_key") or "")
    state["enrage_used"]=True
    state["special_attack_used"]=True
    state["permanent_attack_buff_percent"]=float(enrage.get("permanent_attack_buff_percent",0) or 0)
    plan=build_boss_action_plan(boss,forced_skill_key=special)
    state["last_action_key"]=special
    return {
        "triggered":True,
        "reason":"hp_threshold",
        "action_plan":plan,
        "special_replaces_regular_action":bool(enrage.get("special_replaces_regular_action",True)),
        "events":[
            {"type":"boss_enrage","attack_buff_percent":state["permanent_attack_buff_percent"]},
            {"type":"boss_enrage_special","skill_key":special},
        ],
    }

def prepare_boss_turn(boss: dict[str, Any], rng=None) -> dict[str, Any]:
    """Select exactly one boss action for the current enemy turn.

    Enrage special has priority and replaces the normal weighted action. Once
    used, all future turns use the after-enrage AI table.
    """
    if not boss.get("is_boss"):
        return {"is_boss":False,"enrage_triggered":False,"action_plan":None}
    enrage=trigger_boss_enrage(boss)
    if enrage["triggered"]:
        return {"is_boss":True,"enrage_triggered":True,"action_plan":enrage["action_plan"],"events":enrage["events"]}
    return {"is_boss":True,"enrage_triggered":False,"action_plan":build_boss_action_plan(boss,rng=rng),"events":[]}

def build_boss_damage_request(action_plan: Mapping[str, Any]) -> dict[str, Any] | None:
    """Translate a boss plan to arguments for production calculate_mob_attack()."""
    if not action_plan or action_plan.get("no_damage"):
        return None
    return {
        "mob_attack":max(1,int(round(float(action_plan.get("effective_attack",1) or 1)*float(action_plan.get("damage_multiplier",1.0) or 1.0)))),
        "attack_type":str(action_plan.get("attack_type") or "physical"),
    }

def finalize_boss_turn(boss: dict[str, Any], action_plan: Mapping[str, Any], actual_damage: int=0) -> dict[str, Any]:
    """Apply effects, then decrement buffs that existed before this action.

    Newly applied Battle Cry/Defense Command must retain their full advertised
    duration. Therefore existing timers are captured before effect application.
    """
    state=_boss_state(boss)
    old_attack_turns=int(state.get("attack_buff_turns",0) or 0)
    old_defense_turns=int(state.get("defense_buff_turns",0) or 0)
    effects=apply_boss_action_effects(boss,action_plan,actual_damage=actual_damage)
    skill=action_plan.get("skill") or {}
    if "attack_buff_percent" not in skill and old_attack_turns>0:
        state["attack_buff_turns"]=old_attack_turns-1
        if state["attack_buff_turns"]<=0:
            state["attack_buff_turns"]=0; state["attack_buff_percent"]=0.0
    if not ("pdef_buff_percent" in skill or "mdef_buff_percent" in skill) and old_defense_turns>0:
        state["defense_buff_turns"]=old_defense_turns-1
        if state["defense_buff_turns"]<=0:
            state["defense_buff_turns"]=0
            state["physical_defense_buff_percent"]=0.0
            state["magical_defense_buff_percent"]=0.0
    player_effect=effects.get("player_effect")
    if player_effect:
        apply_player_effect_instruction(boss,player_effect)
    return {"effects":effects,"boss_state":copy.deepcopy(state),"player_effect":player_effect}

def render_boss_action_text(boss: Mapping[str, Any], turn: Mapping[str, Any], actual_damage: int=0, dodged: bool=False) -> str:
    plan=turn.get("action_plan") or {}
    lines=[]
    if turn.get("enrage_triggered"):
        percent=int((boss.get("boss_state") or {}).get("permanent_attack_buff_percent",0) or 0)
        lines.append(f"🌕 {boss.get('name','Бос')} входить у Лють! ATK +{percent}% до кінця бою.")
    name=plan.get("skill_name") or "Атака боса"
    if plan.get("no_damage"):
        skill=plan.get("skill") or {}
        if "attack_buff_percent" in skill:
            lines.append(f"{name}: ATK +{int(skill['attack_buff_percent'])}% на {int(skill.get('duration_turns',0))} ходи.")
        else:
            lines.append(f"{name}: PDEF і MDEF +30% на {int(skill.get('duration_turns',0))} ходи.")
    elif dodged:
        lines.append(f"💨 {name}: гравець ухилився.")
    else:
        lines.append(f"{name}: завдано {int(actual_damage)} шкоди.")
    return "\n".join(lines)

